# Capa: Tantoyuca
LAYER
  NAME "cz3001"
  STATUS ON
  TYPE POLYGON
  CONNECTIONTYPE POSTGIS
  CONNECTION "host=mxsig-db port=5432 dbname=mdm6data user=postgres password=P0stgr3s"
  DATA "the_geom FROM (SELECT gid, the_geom, clv_zona FROM marco_geoestadistico.mun_coordinaciones WHERE clv_zona = 1) AS t1 USING UNIQUE gid USING SRID=900913"

  METADATA
    "wms_title" "Tantoyuca"
    "wms_enable_request" "*"
  END

  CLASS
    NAME "Tantoyuca"
    STYLE
      COLOR 235 151 78
      OPACITY 60
      OUTLINECOLOR 60 60 60
      WIDTH 0.8
    END
  END
END
  
